use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    // The length does not change
    ensures
        a@.len() == old(a@).len(),
    // Every element is moved to its mirror‐position
    ensures
        forall |i: nat|
            i < a@.len() ==>
                a@.index(i) == old(a@).index(a@.len() - 1 - i),
{
    // Take a snapshot of the original contents
    let old_a = a@;
    let n: usize = a.len();
    let mut i: usize = 0;
    // We will overwrite a[0], a[1], …, a[n-1] one by one
    while i < n
        invariant
            // i only grows up to n
            i <= n,
            // length remains n throughout
            a@.len() == n,
            // already written positions satisfy the reverse property
            forall |j: nat|
                j < i ==>
                    a@.index(j) == old_a.index(n - 1 - j),
        decreases
            n - i,
    {
        // Write the mirrored element from the original snapshot
        let v: i32 = old_a.index((n - 1 - i) as nat);
        a[i] = v;
        i = i + 1;
    }
}

} // verus!

